let tableRegistry={},lastRows=[],chat=read('chat',[]),sourceSearch='',sourcePage=0,sourceType='opportunities',sourceStage='All',sourceSort='id',selectedSeller=read('selectedSeller','S001'),cadence='WBR',classificationEdits=read('classifications',[]),metrics;
