const oppCols=[['id','Opportunity',v=>btn('detail',esc(v),`data-id="${esc(v)}"`)],['region','Region'],['stage','Sales stage'],['category','Forecast category'],['amount','Nominal USD',money,'num'],['expected_close','Expected close'],['seller_id','Seller']];
function bars(rows,key,value,formatter=compact){const max=Math.max(1,...rows.map(r=>Math.abs(r[value]||0)));return rows.map(r=>`<div class="bar-row"><span class="bar-label">${esc(r[key])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(r[value]||0)/max*100}%;background:${(r[value]||0)<0?'#a95e3c':'#087b82'}"></div></div><span class="bar-value">${formatter(r[value])}</span></div>`).join('');}
function lineChart(rows,x,series){
 if(!rows.length)return '<p class="empty">No historical observations for this scope.</p>';series=series.filter(s=>rows.some(r=>Number.isFinite(r[s[0]])));if(!series.length)return '<p class="empty">No measured values for this selection.</p>';
 const width=680,height=235,left=64,right=20,top=14,bottom=40,max=Math.max(1,...rows.flatMap(r=>series.map(s=>r[s[0]]||0)));const range=width-left-right;
 const X=i=>left+i*range/Math.max(1,rows.length-1),Y=v=>height-bottom-v/max*(height-top-bottom);
 return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Historical comparison with exact values in the accompanying table">${[0,.5,1].map(v=>`<line x1="${left}" y1="${Y(max*v)}" x2="${width-right}" y2="${Y(max*v)}" stroke="#dfe7e9"/><text x="2" y="${Y(max*v)+4}">${compact(max*v)}</text>`).join('')}${series.map(([k,label,color])=>`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${rows.filter(r=>Number.isFinite(r[k])).map(r=>`${X(rows.indexOf(r))},${Y(r[k])}`).join(' ')}"/>${rows.flatMap((r,i)=>Number.isFinite(r[k])?[`<circle cx="${X(i)}" cy="${Y(r[k])}" r="3" fill="${color}" tabindex="0"><title>${esc(r[x])}: ${esc(label)} ${money(r[k])}</title></circle>`]:[]).join('')}`).join('')}${rows.map((r,i)=>i===0||i===rows.length-1||i%Math.ceil(rows.length/5)===0?`<text x="${X(i)}" y="${height-12}" text-anchor="middle">${esc(String(r[x]).slice(5))}</text>`:'').join('')}</svg><div class="legend">${series.map(s=>`<span><i style="background:${s[2]}"></i>${esc(s[1])}</span>`).join('')}</div>`;
}
const periodRows=()=>metrics.all.filter(r=>['Won','Lost'].includes(r.stage)?G.inPeriod(r.close_date,context):context.mode==='observed'||G.inPeriod(r.expected_close,context));
function group(rows,key,value){return [...new Set(rows.map(r=>r[key]||'Unknown'))].map(k=>({name:k,value:G.sum(rows.filter(r=>(r[key]||'Unknown')===k),value),n:rows.filter(r=>(r[key]||'Unknown')===k).length})).sort((a,b)=>b.value-a.value);}
function previousDate(){return D.dates.filter(x=>x<context.asOf).at(-1)||D.dates[0];}
function flowKey(){return `${context.asOf}|${context.period}|${context.region}|${context.segment}|${context.product}`;}
