function flow(){
 const saved=read('reviews',{});if(saved[flowKey()])return saved[flowKey()];
 const r=revenueFacts().filter(r=>G.inPeriod(r.recognition_date,context));
 return {status:'draft',version:1,bookings:Math.round(metrics.forecast||0),revenue:Math.round(G.sum(r,'amount')),downside:Math.round((metrics.actual||0)+(metrics.weighted||0)*.75),upside:Math.round((metrics.actual||0)+(metrics.weighted||0)*1.2),comment:'',acknowledged:false,selected:[],history:[],humanBrief:'',materialItems:[]};
}
