const RACI_DEFAULT=[{deliverable:'Bookings forecast',R:'Regional contributor',A:'Sales manager',C:'Finance partner',I:'GTM Operations'},{deliverable:'Revenue & Book / Bill',R:'Regional contributor',A:'Finance partner',C:'Sales manager',I:'GTM Operations'},{deliverable:'Metric definitions',R:'Data Science',A:'GTM Operations',C:'Finance partner',I:'Seller Systems'},{deliverable:'Campaign intervention',R:'Marketing',A:'GTM Operations',C:'Sales manager',I:'Finance partner'},{deliverable:'Data quality correction',R:'Seller Systems',A:'GTM Operations',C:'Data Science',I:'Sales manager'}];
