function coverageView(){
 if(context.mode==='observed')return unavailable('Open opportunity amounts, expected close dates and targets are absent from the observed CRM, so monetary coverage and forward outlook cannot be calculated.');
 const periods=['Q1','Q2','Q3','Q4'];
 const rows=periods.map(period=>{const m=G.metrics(D,C,{...context,period});return {period,actual:m.actual,target:m.target,gap:m.gap,pipeline:m.pipeline,weighted:m.weighted,coverage:m.coverage,gapCoverage:m.gapCoverage};});
 const cats=group(metrics.open,'category','amount');
 const total={period:'FY / ratio of sums',actual:G.sum(rows,'actual'),target:metrics.target===null?null:G.sum(rows,'target'),pipeline:G.sum(rows,'pipeline')};total.gap=total.target===null?null:Math.max(0,total.target-total.actual);total.coverage=G.ratio(total.pipeline,total.target);total.gapCoverage=G.ratio(total.pipeline,total.gap);
 const nextPeriod=context.period!=='FY'&&context.period!=='Q4'?'Q'+(Number(context.period.slice(1))+1):null;const nextRow=rows.find(r=>r.period===nextPeriod);const threshold=read('coverage-threshold',3),conv=read('coverage-conversion',.35),weeks=read('coverage-weeks',6),growth=read('coverage-growth',15000);
 return kpis([['Open pipeline',compact(metrics.pipeline),'Eligible expected-close window · known value'],['Whole-plan coverage',multiple(metrics.coverage),'Open pipeline / full period target'],['Remaining-gap coverage',multiple(metrics.gapCoverage),'Open pipeline / max(target − actual, 0)'],['Expected open value',compact(metrics.weighted),'Stage assumptions · capped probabilities']])+panel('Coverage across calendar quarters',table([...rows,total],[['period','Period'],['actual','Bookings',money],['target','Target',money],['pipeline','Open USD',money],['coverage','Plan coverage',multiple],['gapCoverage','Gap coverage',multiple]],'coverage')+`<p class="small">The annual row is a ratio of summed values. This table uses only 2026 calendar quarters with explicit quotas; it does not compare multi-year pipeline against one annual target.</p>`)+`<div class="grid">${panel('Forecast categories',bars(cats,'name','value')+table(cats,[['name','Category'],['value','Nominal USD',money],['n','Opportunities']],'categories'),'Category is distinct from sales stage. Commit remains a call, not a realized outcome.')}${panel('Pipeline sufficiency scenario',`<div class="form-grid">${field('suff-threshold','Coverage hypothesis · ×',threshold,'number','min="0.1" max="20" step="0.1"')}${field('suff-conversion','Within-window conversion · %',conv*100,'number','min="0" max="100" step="1"')}</div><p>At ${pct(conv)} conversion, known open pipeline supports ${money(metrics.pipeline*conv)} against a remaining gap of ${money(metrics.gap)}.</p><p>Threshold hypothesis ${multiple(threshold)}: ${metrics.gapCoverage===null?'N/A':metrics.gapCoverage>=threshold?'met':'not met'}. This is a configurable planning assumption, not a universal 3× rule.</p>${btn('recalculate-coverage','Recalculate assumptions','','primary')}`)}</div>${panel('Next-quarter creation & maturation scenario',`<p class="small">${nextRow?'Forward window: '+nextPeriod+'.':'Next-year demand and quotas are unavailable; this is an explicit creation-only scenario starting from zero supplied pipeline.'}</p><div class="form-grid">${field('forward-weeks','Weekly intervals',weeks,'number','min="1" max="26"')}${field('forward-growth','Net new eligible pipeline / week · USD',growth,'number','min="0" step="1000"')}</div><p>Starting pipeline ${money((nextRow?.pipeline||0))} + ${weeks} intervals × ${money(growth)} = <strong>${money((nextRow?.pipeline||0)+weeks*growth)}</strong>. Expected value at the selected conversion assumption: ${money(((nextRow?.pipeline||0)+weeks*growth)*conv)}.</p><p class="small">The forward window follows the selected quarter when the next quarter is in 2026. Creation assumptions do not edit the stored snapshots or turn carryover into new demand.</p>${btn('recalculate-coverage','Recalculate outlook')} ${link('sales','capacity','Compare with resource capacity →')}`)}${panel('Eligible opportunities',table(metrics.open,oppCols,'coverage-opps',100))}`;
}
function movementsView(){
 if(context.mode==='observed')return unavailable('The CRM source is a final state, not an event log. Weekly movements require the separately generated snapshots.');
 const prev=previousDate(),all=G.bridge(D,C,context,prev),rows=all.filter(r=>r.delta!==0),groups=group(rows,'type','delta');
 const opening=G.sum(all,'opening'),closing=G.sum(all,'closing'),delta=G.sum(all,'delta');
 const pushes=all.filter(r=>r.date_shift_days>0&&r.before&&!['Won','Lost'].includes(r.before.stage)&&r.after&&!['Won','Lost'].includes(r.after.stage));
 const pulls=all.filter(r=>r.date_shift_days<0&&r.before&&!['Won','Lost'].includes(r.before.stage)&&r.after&&!['Won','Lost'].includes(r.after.stage));
 const eventCols=[['id','Opportunity',v=>btn('movement-detail',v,`data-id="${v}"`)],['type','Bridge category'],['previous_close','Before close'],['current_close','After close'],['opening','Opening USD',money],['closing','Closing USD',money],['delta','Change USD',money]];
 return kpis([['Opening pipeline',compact(opening),prev],['Net movement',compact(delta),`${rows.length} non-zero contributions`],['Closing pipeline',compact(closing),context.asOf],['Bridge residual',money(closing-opening-delta),'Opening + movements = closing']])+`<div class="grid">${panel('Changes in eligible pipeline',bars(groups,'name','value')+`<p class="small">Signed contributions; categories are mutually exclusive. Precedence: created → won/lost → window change → amount change. Changes within the window may have zero monetary impact.</p>`)}${panel('Date changes',`<p><strong>${pushes.length} push-outs</strong> and <strong>${pulls.length} pull-ins</strong> among opportunities open at both dates.</p><p>Date changes are a separate diagnostic. A Q3 → Q4 shift can move value out of Q3 while leaving the full-year total unchanged.</p><p>Pull-in expected value is an assumption, conditional on customer readiness and capacity. Check discount cost and next-quarter displacement before changing a commitment.</p>`)}</div>${panel('Full monetary movement ledger',table(rows,eventCols,'movements'))}<div class="grid">${panel('Push-out details',table(pushes,[...eventCols.slice(0,4),['date_shift_days','Days shifted']], 'push-outs'))}${panel('Pull-in details',table(pulls,[...eventCols.slice(0,4),['date_shift_days','Days shifted']], 'pull-ins'))}</div>${actionRegister()}`;
}
function trendView(){
 const rows=context.mode==='planning'?D.dates.filter(d=>d<=context.asOf&&G.inPeriod(d,context)).map(date=>{const m=G.metrics(D,C,{...context,asOf:date});return {date,actual:m.actual,forecast:m.forecast,target:m.target,pipeline:m.pipeline};}):G.monthsIn(context).map(month=>({date:month+'-01',actual:G.sum(metrics.won.filter(r=>r.close_date.slice(0,7)<=month),'amount'),forecast:null,target:null,pipeline:null}));
 const crossing=rows.find((r,i)=>r.target!==null&&r.actual>=r.target&&(i===0||rows[i-1].actual<rows[i-1].target));
 return panel('Bookings and forecast through time',lineChart(rows,'date',context.mode==='planning'?[['actual','Bookings','#087b82'],['forecast','Forecast scenario','#426b9d'],['target','Plan','#a46432']]:[['actual','Cumulative period bookings','#087b82']])+`<div class="callout">${crossing?'The stored series first meets the applicable target on '+esc(crossing.date)+'.':'No target crossing is established in this series.'} Each point uses the snapshot available on that date. Decisions are annotations, not evidence of causality.</div>`+table(rows,[['date','Snapshot / month'],['actual','Bookings',money],['forecast','Scenario forecast',money],['target','Plan',money],['pipeline','Known open USD',money]],'trend'))+panel('Decision timeline',table(actionRows(),[['created','Created'],['title','Decision',esc,'wrap'],['review_on','Review date'],['status','Status'],['outcome','Recorded outcome',esc,'wrap']],'decision-timeline'));
}
function commitConversion(){const issued=D.dates.filter(d=>d<=new Date(Date.parse(context.asOf+'T00:00:00Z')-28*86400000).toISOString().slice(0,10)).at(-1);if(!issued)return '';const current=new Map(metrics.all.map(r=>[r.id,r]));const cohort=G.records(D,C,{...context,asOf:issued}).filter(r=>r.category==='Commit'&&r.expected_close&&r.expected_close<=context.asOf&&G.inPeriod(r.expected_close,context));const won=cohort.filter(r=>current.get(r.id)?.stage==='Won');return panel('Matured commit cohort',kpis([['Commit deals at issue',num(cohort.length),issued+'; expected close within selected period and by current as-of'],['Converted to won',pct(G.ratio(won.length,cohort.length)),won.length+' / '+cohort.length+' deals'],['Committed value converted',pct(G.ratio(G.sum(won,'amount'),G.sum(cohort,'amount'))),'Won cohort issue-time value / all issue-time value'],['Issue-time nominal value',compact(G.sum(cohort,'amount')),'No intent or subjective trust score']])+table(cohort.map(r=>({...r,outcome:current.get(r.id)?.stage||'Not observed'})),[['id','Opportunity'],['amount','Issue-time USD',money],['expected_close','Issue-time close'],['outcome','Current observed stage']],'commit-conversion'));}
function accuracyView(){
 if(context.mode==='observed')return unavailable('There are no historical forecast calls in the observed CRM.');
 if(context.product!=='All'||context.segment!=='All'||context.seller!=='All')return '<div class="callout warn">Forecast calls are stored at region × month × 28-day horizon. Reset product, segment and seller filters to evaluate that grain.</div>';
 const rows=D.forecast_calls.filter(r=>r.target_end<=context.asOf&&(context.region==='All'||r.region===context.region)&&G.inPeriod(r.target_end,context));
 const f=G.forecastQuality(rows);const groups=['Central','East','West'].filter(r=>context.region==='All'||context.region===r).map(region=>({region,...G.forecastQuality(rows.filter(r=>r.region===region))}));
 return kpis([['WAPE',pct(f.wape),`${f.n} matured region-month calls · 28-day horizon`],['Baseline WAPE',pct(f.baselineWape),'Previous completed-month bookings'],['Bias',compact(f.bias),'Mean forecast − actual; signed USD'],['MAE',compact(f.mae),'Mean absolute error · USD']])+`<div class="callout">${f.n?f.wape<f.baselineWape?'The candidate has lower WAPE in this selected synthetic test window. This does not establish performance on business data.':'The candidate does not beat the baseline in this selected synthetic test window. Retain the baseline for this comparison.':'No matured calls in this selection.'} MAPE ${pct(f.mape)} excludes ${f.zeros} zero-actual calls; WAPE uses the sum of actual values.</div>${panel('Comparable regional errors',table(groups,[['region','Region'],['n','Calls'],['bias','Bias',money],['mae','MAE',money],['wape','WAPE',pct],['baselineWape','Baseline WAPE',pct],['mape','MAPE',pct]],'forecast-regions'))}${panel('Frozen forecast calls',table(rows,[['issued_at','Issued'],['target_end','Target month end'],['region','Region'],['forecast','Candidate USD',money],['baseline','Baseline USD',money],['actual','Actual USD',money],['training_n','Prior closed n'],['training_max_close','Last training close']],'forecast-calls')+`<p class="small">The candidate uses only opportunities known at issue time, plus the win rate of previously closed deals. Outcome dates after issuance are excluded from inputs. No model is selected by looking ahead; both methods use the same matured test calls. The scenario was not calibrated to produce a winning model.</p>`)}${commitConversion()}`;
}
