function retentionView(){
 const r=G.recurring(D,context),cutoff=context.asOf.slice(0,7);const all=D.subscriptions.filter(x=>x.month<cutoff&&(context.region==='All'||x.region===context.region)&&(context.segment==='All'||x.segment===context.segment));
 const cohorts=[...new Set(all.map(x=>x.cohort))].flatMap(cohort=>[...new Set(all.filter(x=>x.cohort===cohort).map(x=>x.month))].map(month=>{const rs=all.filter(x=>x.cohort===cohort&&x.month===month),first=all.filter(x=>x.cohort===cohort&&x.month===cohort);return {cohort,month,n:rs.length,logos:rs.filter(x=>x.closing_mrr>0).length,logoRetention:G.ratio(rs.filter(x=>x.closing_mrr>0).length,first.length),valueRetention:G.ratio(G.sum(rs,'closing_mrr'),G.sum(first,'new_mrr'))};}));
 return kpis([['Net revenue retention',pct(r.nrr),`${r.openingLogos} opening paying customers`],['Gross revenue retention',pct(r.grr),'Losses on opening cohort; expansion excluded'],['Logo retention',pct(r.logoRetention),`${r.retainedLogos} retained / ${r.openingLogos} opening`],['Eligible months',num(r.months.length),'Completed months inside selected period']])+panel('Customer and value retention cohorts',table(cohorts,[['cohort','Acquisition cohort'],['month','Observation month'],['n','Original customers'],['logos','Retained customers'],['logoRetention','Logo retention',pct],['valueRetention','Value retention',pct]],'retention-cohorts')+'<p class="small">This table preserves the full completed-month cohort history for comparison; the KPI cards use the selected period. Recent cohorts have fewer observed ages and are right-censored. Value retention can exceed 100% through expansion without new customers; that does not guarantee company-wide growth.</p>')+panel('Event reconciliation',table(r.rows,[['customer_id','Customer'],['month','Month'],['opening_mrr','Opening MRR',money],['new_mrr','New MRR',money],['expansion_mrr','Expansion',money],['contraction_mrr','Contraction',money],['churn_mrr','Churn',money],['closing_mrr','Closing MRR',money]],'subscription-ledger',100))+
 panel('Interpretation limits','<p>Differences between cohorts can reflect age, mix or selection. The subscription ledger demonstrates arithmetic and diagnosis; it does not establish that acquisition targeting caused retention changes.</p>');
}
function paymentsView(){const merchants=D.merchants.filter(m=>m.signed_date<=context.asOf&&(context.region==='All'||m.region===context.region)&&(context.segment==='All'||m.segment===context.segment));const ids=new Set(merchants.map(m=>m.id)),payments=D.payments.filter(p=>ids.has(p.merchant_id)&&p.date<=context.asOf&&G.inPeriod(p.date,context)),success=payments.filter(p=>p.status==='Succeeded');const eligible=merchants.filter(m=>G.days(m.signed_date,context.asOf)>=30),activated=eligible.filter(m=>m.first_payment_date&&G.days(m.signed_date,m.first_payment_date)<=30),cycle=G.median(activated.map(m=>G.days(m.signed_date,m.first_payment_date)));return kpis([['Successful payment volume',compact(G.sum(success,'amount')),'TPV: successful transactions in period'],['Platform fees',compact(G.sum(success,'platform_fee')),'Synthetic 2.5% + $0.30 per success'],['30-day activation',pct(G.ratio(activated.length,eligible.length)),`${activated.length} activated / ${eligible.length} matured signups`],['Time to first payment',num(cycle,1)+' days','Median among activated, matured merchants']])+panel('Merchant activation evidence',table(merchants.map(m=>({...m,matured:G.days(m.signed_date,context.asOf)>=30?'Yes':'Censored',activated:m.first_payment_date&&m.first_payment_date<=context.asOf?'Yes':'No'})),[['id','Merchant'],['region','Region'],['segment','Segment'],['signed_date','Signed up'],['first_payment_date','First success'],['matured','30-day observation'],['activated','Activated by as-of']],'merchants')+'<p class="small">Activation uses the cumulative signup cohort matured by the snapshot; payment values use the selected period. These denominators differ deliberately.</p>')+panel('Payments definitions & attempt ledger',`<p><strong>TPV</strong> is processed successful transaction value. <strong>Platform fees</strong> are simulated fee revenue. Neither is merchant accounting revenue, cash settlement, MRR or ARR. Attempt success is ${pct(G.ratio(success.length,payments.length))} (${success.length}/${payments.length}); this independent fixture has one attempt per payment and cannot measure retry lift.</p>${table(payments,[['id','Payment'],['merchant_id','Merchant'],['date','Date'],['status','Status'],['amount','Attempt amount',money],['platform_fee','Platform fee',money]],'payments',100)}<p class="small">Independent educational case. It does not claim employment or operational experience at Stripe.</p>`);}
