function runEvaluation(){return evaluationCases().map(t=>{const start=performance.now(),answer=G.answer(t.question,D,C,t.context,t.role),latency=performance.now()-start,obtained=t.key?answer.values[t.key]:answer.status,pass=obtained===t.expected&&answer.readOnly&&(answer.status!=='answered'||answer.citations.length>0);return {name:t.name,expected:t.expected,obtained,pass,latency_ms:Math.round(latency*1000)/1000,context:answer.scope,citations:answer.citations.length};});}
