function val(id){return document.getElementById(id)?.value??'';}
function bounded(id,min,max,integer=false){const e=document.getElementById(id),v=Number(e?.value);if(!e||e.value.trim()===''||!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isInteger(v)))throw Error(`${e?.closest('label')?.textContent||id}: enter a ${integer?'whole ':''}number between ${min} and ${max}.`);return v;}
